use std::fs

fn best(pr: Vec<int>) -> int {
    let mut bi: int = 0
    let n: int = pr.len() as int
    let mut i: int = 1
    while i < n {
        if pr[i as usize] > pr[bi as usize] {
            bi = i
        }
        i += 1
    }
    bi
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut names: Vec<string> = []
    let mut pr: Vec<int> = []
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        let n: int = parts.len() as int
        if n == 0 {
            println("error")
        } else if parts[0] == "add" && n == 3 {
            match parts[2].parse::<int>() {
                Ok(p) => {
                    names.push(parts[1])
                    pr.push(p)
                }
                Err(_) => println("error")
            }
        } else if parts[0] == "pop" && n == 1 {
            if names.len() == 0 {
                println("empty")
            } else {
                let b = best(pr)
                println("${names[b as usize]}")
                names.remove(b as usize)
                pr.remove(b as usize)
            }
        } else if parts[0] == "peek" && n == 1 {
            if names.len() == 0 {
                println("empty")
            } else {
                let b = best(pr)
                println("${names[b as usize]}")
            }
        } else if parts[0] == "size" && n == 1 {
            println("${names.len()}")
        } else {
            println("error")
        }
    }
    println("left:")
    while names.len() > 0 {
        let b = best(pr)
        println("${names[b as usize]} ${pr[b as usize]}")
        names.remove(b as usize)
        pr.remove(b as usize)
    }
}

